INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00466-ca0a-7137-b6e0-4fd535d547e8'::uuid, '019f9df7-a2a2-78fc-bd9e-a40e9b4f9363'::uuid, 'A cylindrical pipe has radius 4 cm. Water flows through it at 1.5 metres per second for 10 minutes. Find the volume of water delivered, in litres.', '4524 litres', 'Area = π(4²) = 16π cm². Column length = 150 cm/s × 600 s = 90,000 cm. Volume = 16π × 90,000 = 1,440,000π cm³ = 1440π litres ≈ 4524 litres.', 'Hard', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:50:40.393Z'::timestamptz, '2026-08-15T07:50:40.393Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00466-ca13-76f9-92b2-115a46d9a7da'::uuid, '019f9df7-a2a2-7839-8287-1e75e9dd37f8'::uuid, 'A rectangular field has length 24 m and width 15 m. Its length is increased by 12% while its width is decreased by 10%. Find the percentage change in its area.', '0.8% increase', 'Multiplier for area = 1.12 × 0.90 = 1.008. Percentage change = (1.008 - 1) × 100% = +0.8%.', 'Easy', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:50:40.403Z'::timestamptz, '2026-08-15T07:50:40.403Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00466-ca1c-7d26-87fa-c271fc993d72'::uuid, '019f9df7-a2a2-7839-8287-1e75e9dd37f8'::uuid, 'A deposit earns 3.5% compound interest per year. After 4 years, the total interest earned is $742. Find the initial deposit, correct to the nearest dollar.', '$5030', 'Interest = P[(1.035)⁴ - 1] = 742. P = 742 / [(1.035)⁴ - 1] ≈ 742 / 0.14752 ≈ $5030.', 'Medium', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:50:40.412Z'::timestamptz, '2026-08-15T07:50:40.412Z'::timestamptz) ON CONFLICT (id) DO NOTHING;